            SaveFileDialog savefile = new SaveFileDialog();            // set a default file name            savefile.FileName = "Lesson_01.txt";            // set filters - this can be done in properties as well            savefile.Filter = "Text files (*.txt)|*.txt|All files (*.*)|*.*";            if (savefile.ShowDialog() == DialogResult.OK) {                using (StreamWriter sw = new StreamWriter(savefile.FileName))                    sw.WriteLine("Hello World!");            }